type DeviceAction =
	| { type: "command"; label: string; value: string }
	| { type: "link"; label: string; href: string; icon?: ReactNode };

interface DeviceTarget {
	id: string;
	name: string;
	icon: ReactNode;
	description: string;
	actions: DeviceAction[];
}

function buildTargets(owner: string): DeviceTarget[] {
	const cliCommand = `npm i -g @lobu/cli\nlobu login\nlobu memory configure --url ${buildMcpUrl(owner)}`;
	return [
		{
			id: "mac",
			name: "macOS app",
			icon: APPLE_ICON,
			description:
				"Menu bar app. Syncs local folders, Screen Time, and browser history into your workspace. Currently in private beta — book a call for access.",
			actions: [
				{
					type: "link",
					label: "Contact us",
					href: MAC_CONTACT_URL,
					icon: <CalendarClock className="h-3 w-3" />,
				},
			],
		},
		{
			id: "extension",
			name: "Chrome extension",
			icon: <Chrome className="h-4 w-4" />,
			description:
				"Browser extension for Chrome. Lets agents read the current page and run browser actions in your session, and pairs this workspace for one-click auth.",
			actions: [
				{
					type: "link",
					label: "Add to Chrome",
					href: "https://chromewebstore.google.com/detail/jhgcecbdpnoehfnhpdfihlchjddapepi",
				},
			],
		},
		{
			id: "cli",
			name: "CLI",
			icon: <Terminal className="h-4 w-4" />,
			description:
				"The Lobu CLI authenticates local tools (Claude Code, Cursor, MCP clients) against this workspace. Headless, no GUI.",
			actions: [
				{ type: "command", label: "Install + log in", value: cliCommand },
			],
		},
		{
			id: "docker",
			name: "Docker",
			icon: DOCKER_ICON,
			description:
				"Self-hosted bridge in a container. Run on a server or VPS to host connectors that need a persistent always-on environment.",
			actions: [
				{ type: "command", label: "Run command", value: DOCKER_COMMAND },
			],
		},
	];
}

export function DeviceConnect({
	owner,
	onClose,
}: {
	owner: string;
	onClose?: () => void;
}) {
	const targets = useMemo(() => buildTargets(owner), [owner]);
	const [openId, setOpenId] = useState<string | null>(targets[0]?.id ?? null);
	const [copiedKey, setCopiedKey] = useState<string | null>(null);

	const copy = async (key: string, text: string) => {
		if (typeof navigator === "undefined" || !navigator.clipboard) return;
		try {
			await navigator.clipboard.writeText(text);
			setCopiedKey(key);
			setTimeout(() => setCopiedKey(null), 1500);
		} catch {
			// noop
		}
	};

	return (
		<div className="space-y-2">
			<div className="overflow-hidden rounded-lg border">
			{targets.map((target, idx) => {
				const open = openId === target.id;
				return (
					<div
						key={target.id}
						className={idx === targets.length - 1 ? "" : "border-b"}
					>
						<button
							type="button"
							onClick={() => setOpenId(open ? null : target.id)}
							aria-expanded={open}
							className="flex w-full items-center gap-2 px-3 py-2.5 text-left transition-colors hover:bg-accent/40"
						>
							<span className="text-muted-foreground">{target.icon}</span>
							<span className="flex-1 text-sm font-medium">{target.name}</span>
							<ChevronDown
								className={cn(
									"h-4 w-4 shrink-0 text-muted-foreground transition-transform",
									open && "rotate-180",
								)}
							/>
						</button>
						{open ? (
							<div className="space-y-2 px-3 pb-3">
								<p className="text-xs text-muted-foreground">
									{target.description}
								</p>
								<div className="flex flex-wrap gap-2">
									{target.actions.map((action) =>
										action.type === "command" ? (
											<CommandPopover
												key={`${target.id}-${action.label}`}
												command={action.value}
												buttonLabel={action.label}
												copied={copiedKey === `${target.id}:${action.label}`}
												onCopy={() =>
													void copy(`${target.id}:${action.label}`, action.value)
												}
											/>
										) : (
											<a
												key={`${target.id}-${action.label}`}
												href={action.href}
												target="_blank"
												rel="noreferrer"
												className="inline-flex items-center gap-1 rounded-md border border-border px-2 py-1 text-xs font-medium text-primary"
											>
												{action.icon ?? <Download className="h-3 w-3" />}
												{action.label}
												<ArrowUpRight className="h-3 w-3" />
											</a>
										),
									)}
								</div>
							</div>
						) : null}
					</div>
				);
			})}
			</div>
			<FormFooter onCancel={onClose} />
		</div>
	);
}
