/**
 * Devices list: your paired Mac / Chrome extension / CLI as runtimes. Devices
 * are user-owned and private ("Yours") — they follow you across workspaces — so
 * they carry that badge even on this org-scoped page.
 *
 * Device pairing surface (user menu → My devices). Device-bound connectors
 * appear under Connect with the On device filter; sandboxes are connector
 * kinds (Runtime facet) on the same list.
 */
export function DevicesBody({ owner }: { owner: string }) {
	const { data: devices = [], isLoading } = useDevices();
	const [adding, setAdding] = useState(false);

	return (
		<InfraTabScaffold
			lede="Pair a device to run device-bound connectors."
			addLabel="Add a device"
			adding={adding}
			onStartAdd={() => setAdding(true)}
			isLoading={isLoading}
			loadingSkeleton={<InfraListSkeleton />}
			isEmpty={devices.length === 0}
			emptyIcon={MonitorSmartphone}
			emptyTitle="No devices connected"
			emptyDescription="Pair a Mac, browser extension, or CLI to run device-bound connectors."
			form={<DeviceConnect owner={owner} onClose={() => setAdding(false)} />}
		>
			{devices.map((device, idx) => (
				<Link
					key={device.id}
					to="/$owner/connectors/runtime/devices/$deviceId"
					params={{ owner, deviceId: device.id }}
					search={{ provider: undefined }}
					className={`flex items-center gap-3 px-3 py-2.5 hover:bg-accent/40 ${idx === devices.length - 1 ? "" : "border-b"}`}
				>
					<PlatformIcon platform={inferredPlatform(device)} />
					<span className="min-w-0 flex-1 truncate text-sm font-medium">
						{deviceName(device)}
					</span>
					<span className="rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
						Yours · private
					</span>
					<DeviceStatusDot online={device.online} />
				</Link>
			))}
		</InfraTabScaffold>
	);
}
