// registry stays readable as new device kinds land.
export const BROWSER_CAPABILITIES = [
  "browser.tabs",
  "browser.scripting",
  "browser.history",
  "browser.bookmarks",
  "browser.downloads",
  "browser.notifications",
  "browser.debugger",
  // browser.cookies intentionally absent in v1 — high-trust, not approved
] as const;

export const OS_CAPABILITIES = [
