const PLATFORM_ALLOWLIST: Record<string, readonly string[]> = {
  macos: [
    ...OS_CAPABILITIES,
    ...BROWSER_CAPABILITIES,
    ...MAC_DEVICE_CAPABILITIES,
  ],
  ios: IOS_CAPABILITIES,
