import type { ConnectorAuthMethod, ConnectorAuthSchema } from "@lobu/connector-sdk";
import type { ConnectorDefinitionItem } from "@/lib/api";

export type AppInstallTarget = {
	connectorKey: string;
	provider: string;
	installShape: "oauth-code-exchange" | "github-app" | null;
};

function lower(value: string | null | undefined): string | null {
	const normalized = value?.trim().toLowerCase();
	return normalized || null;
}

function authMethods(
	schema: Record<string, unknown> | null | undefined,
): ConnectorAuthMethod[] {
	return (schema as ConnectorAuthSchema | null | undefined)?.methods ?? [];
}

/**
 * Find the connector a brand-new `<provider>` social signup should continue
 * into for an app install: it must declare BOTH a login OAuth method for the
 * provider (an identity method — one carrying `loginScopes`) AND an
 * `app_installation` method for the same provider. The login method is what let
 * the user sign in; the app_installation method is the "Add to <app>" handshake
 * we send them to next.
 *
 * Mirrors the gateway's connector-auth matching, but runs entirely on the
 * `auth_schema` the SPA already loads — so no server round-trip or stored intent
 * is needed. better-auth's `newUserCallbackURL` is what guarantees only genuine
 * new users reach this path; here we only resolve which connector to install.
 */
export function resolveAppInstallTarget(
	connectors: ConnectorDefinitionItem[],
	providerId: string | null | undefined,
): AppInstallTarget | null {
	const provider = lower(providerId);
	if (!provider) return null;

	for (const connector of connectors) {
		const methods = authMethods(connector.auth_schema);

		const hasLogin = methods.some(
			(method) =>
				method.type === "oauth" &&
				lower(method.provider) === provider &&
				Array.isArray(method.loginScopes) &&
				method.loginScopes.length > 0,
		);
		if (!hasLogin) continue;

		const appInstall = methods.find(
			(method): method is Extract<ConnectorAuthMethod, { type: "app_installation" }> =>
				method.type === "app_installation" && lower(method.provider) === provider,
		);
		if (!appInstall) continue;

		return {
			connectorKey: connector.key,
			provider,
			installShape: appInstall.installShape ?? null,
		};
	}
	return null;
}
