/**
 * Recognises Lobu's first-party surfaces (CLI, Mac/iOS bridges) so the UI can
 * fold them into a "your devices & tools" group instead of listing them
 * alongside third-party MCP apps. Prefers the exact software-id allowlist;
 * the name check is a best-effort fallback for clients that register without a
 * known software id.
 *
 * `name` must be the REGISTERED `client_name`, never the per-session
 * `clientInfo.name` — that one names the driving process, so a first-party app
 * driven by a third-party runtime would fail its own check.
 *
 * Both signals are self-asserted at dynamic registration and could be spoofed.
 * This is a display category ONLY. Never gate access, visibility, or
 * deduplication on it.
 */
function isFirstPartyLobuClient(
	name: string | null,
	softwareId: string | null,
): boolean {
	const s = (softwareId ?? "").trim().toLowerCase();
	if (s && LOBU_FIRST_PARTY_SOFTWARE_IDS.has(s)) return true;
	const n = (name ?? "").trim().toLowerCase();
	return (
		n === "lobu" ||
		n === "owletto" ||
		n.startsWith("lobu ") ||
		n.startsWith("lobu-") ||
		n.startsWith("owletto ") ||
		n.startsWith("owletto-")
	);
}

