import { DEVICE_ROW_KEY_PREFIX } from "@lobu/core/reserved";
import type {
	ConnectionFacets,
	ConnectorDefinitionItem,
	DeviceWorkerItem,
} from "@/lib/api/connections";
import { deviceName, inferredPlatform } from "@/components/devices/device-display";

/**
 * Paired devices as connectors-list rows.
 *
 * Same read-layer union as `sandbox-rows.ts` / `inference-rows.ts`: a device is
 * NOT a `connections` row, it lives in `device_workers`. It belongs on this
 * list because a device and a remote sandbox answer the same question — where
 * an agent's work runs — and the sandbox lede already frames itself as "instead
 * of the built-in local runtime".
 *
 * The connectors a device PROVIDES (Screen Time, Photos, Chrome history) are
 * separate rows, wired by `ensureDeviceConnectorWired` on the server. A device
 * row is the host those rows depend on: when the laptop sleeps they all go
 * stale at once, and this row is where that shows.
 */

export { DEVICE_ROW_KEY_PREFIX };

const RUNTIME_ONLY_FACETS: ConnectionFacets = {
	data: false,
	chat: false,
	actions: false,
	audience: false,
	inference: false,
	runtime: true,
};

export function parseDeviceRowKey(connectorKey: string): string | null {
	if (!connectorKey.startsWith(DEVICE_ROW_KEY_PREFIX)) return null;
	const id = connectorKey.slice(DEVICE_ROW_KEY_PREFIX.length);
	return id.length > 0 ? id : null;
}

export function isDeviceConnectorKey(connectorKey: string): boolean {
	return parseDeviceRowKey(connectorKey) !== null;
}

/** Human label for the platform a device reports, for the row's meta line. */
export function devicePlatformLabel(platform: string | null): string {
	if (platform === "macos") return "macOS";
	if (platform === "ios") return "iOS";
	if (platform === "chrome-extension") return "Chrome";
	// A bridge that polls without declaring a platform registers fine but can
	// advertise no capabilities — say so rather than inventing a name for it.
	return platform ?? "Unknown platform";
}

export interface DeviceConnectorRow {
	connector: ConnectorDefinitionItem;
	facets: ConnectionFacets;
	device: DeviceWorkerItem;
}

/**
 * Devices as list rows, one per device instance (sandboxes do the same; the
 * per-*class* entries — "Owletto for Mac" — are catalog rows, not list rows).
 *
 * `status` deliberately does NOT reuse the sandbox convention of
 * `error`-when-unusable: a sandbox without a credential is broken, whereas an
 * offline device is usually a closed laptop. Rendering routine sleep as an
 * error trains people to ignore the colour.
 */
export function buildDeviceConnectorRows(
	devices: readonly DeviceWorkerItem[],
): DeviceConnectorRow[] {
	return devices.map((device) => ({
		device,
		facets: RUNTIME_ONLY_FACETS,
		connector: {
			key: `${DEVICE_ROW_KEY_PREFIX}${device.id}`,
			name: deviceName(device),
			description: null,
			version: "",
			auth_schema: null,
			feeds_schema: null,
			actions_schema: null,
			options_schema: null,
			status: device.online ? "active" : "inactive",
			login_enabled: false,
			installed: true,
		} as ConnectorDefinitionItem,
	}));
}

/** The row's secondary line: platform, what it serves, and whether it's awake. */
export function deviceRowMeta(device: DeviceWorkerItem): string {
	const platform = devicePlatformLabel(inferredPlatform(device));
	const count = device.connector_count;
	const connectors = `${count} ${count === 1 ? "connector" : "connectors"}`;
	return [platform, connectors, device.online ? "online" : "offline"].join(" · ");
}

import { CLIENT_ROW_KEY_PREFIX } from "@lobu/core/reserved";
import type { ConnectedClientItem } from "@/lib/api/clients";
import type {
	ConnectionFacets,
	ConnectorDefinitionItem,
} from "@/lib/api/connections";

/**
 * Connected MCP clients as connectors-list rows.
 *
 * A client is the one INBOUND thing on this page: ChatGPT calling in with a
 * person's access, rather than something an agent reaches out to. It earns a
 * place here because the page is the workspace's connection inventory and
 * revoking a grant belongs with it — but it is rendered in its own labelled
 * section, never sorted in among the connectors, because "what can this do for
 * my agents" (the facet axis every other row is filtered on) is the wrong
 * question to ask of it.
 *
 * Clients also surface in Recent, which answers the different question of what
 * has been active lately. Both link to the same `client:{id}` detail.
 */

export { CLIENT_ROW_KEY_PREFIX };

/** Clients advertise no agent-facing capability; every facet is false. */
const NO_FACETS: ConnectionFacets = {
	data: false,
	chat: false,
	actions: false,
	audience: false,
	inference: false,
	runtime: false,
};

/**
 * One row per app, not per registration.
 *
 * A client that re-registers gets a new `oauth_clients` row under the same
 * name, so listing raw registrations shows the same app several times and
 * makes Revoke ambiguous about what it disconnects. The group key comes from
 * the SERVER (`registrationGroupKey` = client_name + owner + org) rather than
 * being re-derived here, so what the UI collapses is exactly what
 * `?scope=all` revokes.
 */
export interface ClientGroup {
	key: string;
	/** Routable id — the group's primary client. Stable and URL-safe. */
	clientId: string;
	title: string;
	/** The process driving the connection, when it differs from the app. */
	drivenBy: string | null;
	clientIds: string[];
	connected: boolean;
	lastSeenAt: number | null;
	linkedUser: string | null;
}

export function groupClients(clients: ConnectedClientItem[]): ClientGroup[] {
	const groups = new Map<string, ClientGroup>();

	for (const client of clients) {
		if (client.kind !== "mcp") continue;

		const title = client.title?.trim() || client.identifier || "Unknown app";
		const key = client.registrationGroupKey || client.id;

		const existing = groups.get(key);
		if (!existing) {
			groups.set(key, {
				key,
				clientId: client.id,
				title,
				drivenBy: client.drivenBy?.trim() || null,
				clientIds: [client.id],
				connected: client.status === "connected",
				lastSeenAt: client.lastSeenAt ?? null,
				linkedUser: client.linkedUserName ?? client.linkedUserEmail ?? null,
			});
			continue;
		}

		existing.clientIds.push(client.id);
		existing.connected = existing.connected || client.status === "connected";
		if ((client.lastSeenAt ?? 0) > (existing.lastSeenAt ?? 0)) {
			existing.lastSeenAt = client.lastSeenAt ?? null;
			// The freshest registration also supplies the driver worth showing.
			existing.drivenBy = client.drivenBy?.trim() || null;
		}
	}

	return [...groups.values()].sort(
		(a, b) => (b.lastSeenAt ?? 0) - (a.lastSeenAt ?? 0),
	);
}

export function parseClientRowKey(connectorKey: string): string | null {
	if (!connectorKey.startsWith(CLIENT_ROW_KEY_PREFIX)) return null;
	const id = connectorKey.slice(CLIENT_ROW_KEY_PREFIX.length);
	return id.length > 0 ? id : null;
}

export function isClientConnectorKey(connectorKey: string): boolean {
	return parseClientRowKey(connectorKey) !== null;
}

export interface ClientConnectorRow {
	connector: ConnectorDefinitionItem;
	facets: ConnectionFacets;
	group: ClientGroup;
}

export function buildClientConnectorRows(
	groups: readonly ClientGroup[],
): ClientConnectorRow[] {
	return groups.map((group) => ({
		group,
		facets: NO_FACETS,
		connector: {
			key: `${CLIENT_ROW_KEY_PREFIX}${group.clientId}`,
			name: group.title,
			description: null,
			version: "",
			auth_schema: null,
			feeds_schema: null,
			actions_schema: null,
			options_schema: null,
			status: group.connected ? "active" : "inactive",
			login_enabled: false,
			installed: true,
		} as ConnectorDefinitionItem,
	}));
}

export function relativeTime(ms: number | null): string {
	if (!ms) return "never";
	const diff = Date.now() - ms;
	if (diff < 60_000) return "just now";
	const mins = Math.floor(diff / 60_000);
	if (mins < 60) return `${mins}m ago`;
	const hours = Math.floor(mins / 60);
	if (hours < 24) return `${hours}h ago`;
	return `${Math.floor(hours / 24)}d ago`;
}

/** The row's secondary line: who granted it, and whether it is still live. */
export function clientRowMeta(group: ClientGroup): string {
	const parts = [group.linkedUser];
	parts.push(
		group.connected ? `active ${relativeTime(group.lastSeenAt)}` : "disconnected",
	);
	// "driven by claude-code" is the honest disambiguator when two different
	// apps ride the same runtime — without it the list showed two rows both
	// titled claude-code and Revoke was unattributable.
	if (group.drivenBy && group.drivenBy !== group.title) {
		parts.push(`via ${group.drivenBy}`);
	}
	return parts.filter(Boolean).join(" · ");
}

