input.new_string:
/**
 * Whether a connector runs on a device (needs a local runtime to execute).
 *
 * A synthesized `device:` row carries neither `runtime` nor
 * `required_capability` — it IS the device, not something bound to one — so it
 * is matched by prefix. Without this, "On device" listed Screen Time and
 * Photos but not a single actual device, and the devices hid under Runtime
 * next to remote sandboxes.
 */
export function connectorIsDeviceBound(
  connector: ConnectorDefinitionItem
): boolean {
  return (
    isDeviceConnectorKey(connector.key) ||
    !!connector.runtime ||
    !!connector.required_capability
  );
}

