import { parseClientRowKey } from "@/lib/connectors/client-rows";
import { parseDeviceRowKey } from "@/lib/connectors/device-rows";
import { parseInferenceRowKey } from "@/lib/connectors/inference-rows";
import {
	parseSandboxProviderKey,
	parseSandboxRowKey,
} from "@/lib/connectors/sandbox-rows";

/**
 * What a routable connector key actually stands for.
 *
 * The connectors list and detail route are a read-layer union over five source
 * tables. Each family used to be recognised by its own `parse*Key` call, which
 * meant every new one had to be added to the list synthesis, the detail
 * branch, AND the route loader's prefetch guard — and the loader was the one
 * that got forgotten, firing a connector-definition prefetch for keys no
 * connector table has ever heard of.
 *
 * One resolver, one place to add the next family.
 */
export type ConnectorRowKind =
	| "connector"
	| "inference"
	| "sandbox"
	| "sandbox-provider"
	| "device"
	| "client";

export interface ResolvedRowKind {
	kind: ConnectorRowKind;
	/** The remainder after the prefix; null for a real connector key. */
	id: string | null;
}

export function resolveConnectorRowKind(connectorKey: string): ResolvedRowKind {
	const inference = parseInferenceRowKey(connectorKey);
	if (inference !== null) return { kind: "inference", id: inference };

	const sandbox = parseSandboxRowKey(connectorKey);
	if (sandbox !== null) return { kind: "sandbox", id: sandbox };

	const sandboxProvider = parseSandboxProviderKey(connectorKey);
	if (sandboxProvider !== null) {
		return { kind: "sandbox-provider", id: sandboxProvider };
	}

	const device = parseDeviceRowKey(connectorKey);
	if (device !== null) return { kind: "device", id: device };

	const client = parseClientRowKey(connectorKey);
	if (client !== null) return { kind: "client", id: client };

	return { kind: "connector", id: null };
}

/**
 * Whether this key names a row backed by `connector_definitions` — i.e. the
 * only kind for which prefetching connector defs and connections is useful.
 */
export function isRealConnectorKey(connectorKey: string): boolean {
	return resolveConnectorRowKind(connectorKey).kind === "connector";
}

