import { Link } from "@tanstack/react-router";
import { AppWindow } from "lucide-react";
import { useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import { useConnectedClients, useRevokeMcpClient } from "@/lib/api/clients";
import { groupClients, relativeTime } from "@/lib/connectors/client-rows";

/**
 * A connected MCP client, rendered through the connectors detail route as
 * `client:{id}`.
 *
 * This page carries Revoke, which is the reason the standalone
 * `/connectors/apps` page could be deleted in the same change rather than
 * waiting on Recent: revoking a grant had exactly one home in the SPA, and it
 * moved here.
 *
 * Identity deliberately shows BOTH names. `client_name` is what the app
 * registered as and is the row's identity; `clientInfo.name` names the process
 * driving the connection. Before they were separated, Owletto for Mac and
 * Claude both rendered as "claude-code" — two rows, same title, and no way to
 * tell which grant Revoke would kill.
 */
export function ClientDetail({
	ownerSlug,
	clientId,
}: {
	ownerSlug: string;
	clientId: string;
}) {
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const { data: clients = [], isLoading } = useConnectedClients(null);
	const revoke = useRevokeMcpClient();
	const [confirming, setConfirming] = useState(false);

	const group = useMemo(
		() => groupClients(clients).find((g) => g.clientId === clientId),
		[clients, clientId],
	);
	// The raw registrations behind the group — each is a separate OAuth grant.
	const registrations = useMemo(
		() => clients.filter((c) => group?.clientIds.includes(c.id)),
		[clients, group],
	);

	if (isLoading) {
		return (
			<div className="space-y-6 p-6">
				<div className="flex items-center gap-3">
					<Skeleton className="h-6 w-6 rounded-md" />
					<div className="space-y-1.5">
						<Skeleton className="h-7 w-48" />
						<Skeleton className="h-3 w-32" />
					</div>
				</div>
			</div>
		);
	}

	if (!group) {
		return (
			<div className="space-y-3 p-6">
				<p className="text-sm text-muted-foreground">App not found.</p>
				<Link
					to="/$owner/connectors"
					params={{ owner: ownerSlug }}
					search={{}}
					className="text-sm text-primary hover:underline"
				>
					Go to Connectors
				</Link>
			</div>
		);
	}

	const primary = registrations[0];
	const redirectUris = (primary?.details?.redirectUris ?? []) as string[];
	const rows: Array<{ label: string; value: string }> = [
		{ label: "Registered", value: group.title },
		...(group.drivenBy && group.drivenBy !== group.title
			? [{ label: "Driven by", value: group.drivenBy }]
			: []),
		...(primary?.platform ? [{ label: "Software", value: primary.platform }] : []),
		...(redirectUris.length > 0
			? [{ label: "Redirects", value: redirectUris.join(", ") }]
			: []),
		{ label: "Granted by", value: group.linkedUser ?? "—" },
		{
			label: "Last active",
			value: group.connected ? relativeTime(group.lastSeenAt) : "disconnected",
		},
		{
			label: "Registrations",
			value: String(group.clientIds.length),
		},
	];

	return (
		<div className="flex w-full max-w-3xl flex-1 flex-col gap-6 p-6">
			<div className="flex items-start gap-3">
				<span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md border">
					<AppWindow className="h-4.5 w-4.5 text-muted-foreground" />
				</span>
				<div className="min-w-0 flex-1">
					<div className="flex flex-wrap items-center gap-2">
						<h1 className="truncate text-xl font-semibold">{group.title}</h1>
						<Badge
							variant={group.connected ? "secondary" : "outline"}
							className="text-[10px]"
						>
							{group.connected ? "Connected" : "Disconnected"}
						</Badge>
					</div>
					<p className="text-xs text-muted-foreground">
						Connects into this workspace over MCP as{" "}
						{group.linkedUser ?? "a member"}, with that person's access.
					</p>
				</div>
			</div>

			<div className="overflow-hidden rounded-lg border text-xs">
				<dl className="divide-y">
					{rows.map((row) => (
						<div key={row.label} className="flex gap-3 px-3 py-2">
							<dt className="w-28 shrink-0 text-muted-foreground">
								{row.label}
							</dt>
							<dd className="min-w-0 flex-1 break-words">{row.value}</dd>
						</div>
					))}
				</dl>
			</div>

			{isAdmin && group.connected ? (
				<div className="space-y-2 rounded-lg border p-3">
					<div className="space-y-0.5">
						<h2 className="text-sm font-medium">Revoke access</h2>
						<p className="text-xs text-muted-foreground">
							Disconnects every registration this app holds
							{group.clientIds.length > 1
								? ` (${group.clientIds.length} of them)`
								: ""}{" "}
							and kills its live sessions. It can reconnect by authorizing
							again.
						</p>
					</div>
					{confirming ? (
						<div className="flex items-center gap-2">
							<Button
								variant="destructive"
								size="sm"
								className="h-7 px-2 text-xs"
								disabled={revoke.isPending}
								onClick={() =>
									revoke.mutate(
										{ clientId: group.clientIds[0], scope: "all" },
										{ onSettled: () => setConfirming(false) },
									)
								}
							>
								{revoke.isPending ? "Revoking…" : "Confirm revoke"}
							</Button>
							<Button
								variant="ghost"
								size="sm"
								className="h-7 px-2 text-xs"
								disabled={revoke.isPending}
								onClick={() => setConfirming(false)}
							>
								Cancel
							</Button>
						</div>
					) : (
						<Button
							variant="outline"
							size="sm"
							className="h-7 px-2 text-xs text-destructive hover:text-destructive"
							onClick={() => setConfirming(true)}
						>
							Revoke
						</Button>
					)}
				</div>
			) : null}
		</div>
	);
}

