/**
 * `oauth_clients.redirect_uris` is a Postgres `text[]`, but the gateway runs
 * with `fetch_types: false`, so it arrives as the raw array literal
 * `{https://a,https://b}` — a STRING — rather than an array. Measured against
 * prod 2026-07-31. Accept both: the string shape is what deployed servers
 * return today, and the array shape is what they should return.
 */
function normalizeRedirectUris(value: unknown): string[] {
	if (Array.isArray(value)) return value.filter((v): v is string => !!v);
	if (typeof value !== "string") return [];
	const inner = value.trim().replace(/^\{/, "").replace(/\}$/, "");
	if (!inner) return [];
	return inner
		.split(",")
		.map((uri) => uri.trim().replace(/^"(.*)"$/, "$1"))
		.filter(Boolean);
}

