import { createFileRoute } from "@tanstack/react-router";
import { DeviceDetail } from "@/components/devices/device-detail";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { useDevices } from "@/lib/api/connections";

/**
 * A paired device: `/connectors/device/{id}`.
 *
 * Its own route rather than a `device:{id}` key on `$connectorKey`. The
 * prefixed-key trick exists so model providers and sandboxes can share the
 * single `$connectorKey` param without a provider named `slack` colliding with
 * the real Slack connector — a static segment has no such problem, and it
 * spares the URL a `%3A`. `device` is reserved as a connector key in
 * `@lobu/core/reserved` so the static segment can never shadow a real one.
 */
export const Route = createFileRoute("/$owner/connectors/device/$deviceId")({
	// Best-effort warm of the devices list; the page renders its own
	// loading / not-found states, so a failure here must not replace the page
	// chrome with the generic route-error UI.
	loader: ({ context: { queryClient } }) =>
		queryClient.prefetchQuery(useDevices.queryOptions()),
	component: DeviceDetailPage,
});

function DeviceDetailPage() {
	const { owner, deviceId } = Route.useParams();
	return (
		<OwnerWorkspaceGate owner={owner}>
			{({ ownerSlug }) => (
				<DeviceDetail ownerSlug={ownerSlug} deviceId={deviceId} />
			)}
		</OwnerWorkspaceGate>
	);
}

import { createFileRoute } from "@tanstack/react-router";
import { ClientDetail } from "@/components/clients/client-detail";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";

/**
 * A connected MCP client: `/connectors/client/{id}`.
 *
 * Routed on `oauth_clients.id`, not the registration group key. The group key
 * embeds `client_name`, which is supplied by the client at dynamic
 * registration — it is attacker-controlled, may contain `/`, and changes when
 * an app re-registers under a different name, so it is neither URL-safe nor
 * stable enough to bookmark. The detail page re-derives the group from the id.
 */
export const Route = createFileRoute("/$owner/connectors/client/$clientId")({
	component: ClientDetailPage,
});

function ClientDetailPage() {
	const { owner, clientId } = Route.useParams();
	return (
		<OwnerWorkspaceGate owner={owner}>
			{({ ownerSlug }) => (
				<ClientDetail ownerSlug={ownerSlug} clientId={clientId} />
			)}
		</OwnerWorkspaceGate>
	);
}

