import pathlib
p = pathlib.Path('src/lib/connectors/row-kinds.ts')
p.write_text('''import { parseInferenceRowKey } from "@/lib/connectors/inference-rows";
import {
\tparseSandboxProviderKey,
\tparseSandboxRowKey,
} from "@/lib/connectors/sandbox-rows";

/**
 * What a routable connector key actually stands for.
 *
 * Model providers and sandboxes are namespaced INTO the `$connectorKey` param
 * with a `prefix:` because they share that one detail route. Each used to be
 * recognised by its own `parse*Key` call at three separate places — the list
 * synthesis, the detail branch, and the route loader's prefetch guard — and
 * the loader was the one that got forgotten, firing connector-definition
 * prefetches for keys no connector table has heard of.
 *
 * Devices and clients are deliberately NOT here: they have their own static
 * routes (`/connectors/device/{id}`, `/connectors/client/{id}`), which keeps
 * their URLs free of a percent-encoded colon.
 */
export type ConnectorRowKind =
\t| "connector"
\t| "inference"
\t| "sandbox"
\t| "sandbox-provider";

export interface ResolvedRowKind {
\tkind: ConnectorRowKind;
\t/** The remainder after the prefix; null for a real connector key. */
\tid: string | null;
}

export function resolveConnectorRowKind(connectorKey: string): ResolvedRowKind {
\tconst inference = parseInferenceRowKey(connectorKey);
\tif (inference !== null) return { kind: "inference", id: inference };

\tconst sandbox = parseSandboxRowKey(connectorKey);
\tif (sandbox !== null) return { kind: "sandbox", id: sandbox };

\tconst sandboxProvider = parseSandboxProviderKey(connectorKey);
\tif (sandboxProvider !== null) {
\t\treturn { kind: "sandbox-provider", id: sandboxProvider };
\t}

\treturn { kind: "connector", id: null };
}

/**
 * Whether this key names a row backed by `connector_definitions` — i.e. the
 * only kind for which prefetching connector defs and connections is useful.
 */
export function isRealConnectorKey(connectorKey: string): boolean {
\treturn resolveConnectorRowKind(connectorKey).kind === "connector";
}
''')
