258					} as ConnectorDefinitionItem & { facets?: ConnectionFacets });
259				}
260			}
261	
262			// Model-provider rows, synthesized from `inference_providers`. They carry
263			// no group, no auth profiles, and no setup state — a provider without a
264			// working key surfaces that as its own `status`, not as "needs setup".
265			const providerItems = buildInferenceConnectorRows(inferenceProviders).map(
266				(row) => ({
267					connector: row.connector,
268					group: undefined,
269					profileCounts: {
270						env: 0,
271						oauth_app: 0,
272						oauth_account: 0,
273						browser_session: 0,
274					},
275					facets: row.facets,
276					needsSetup: false,
277					provider: row.provider as InferenceProviderItem | undefined,
278					sandbox: undefined as SandboxItem | undefined,
279					device: undefined as DeviceWorkerItem | undefined,
280				}),
281			);
282	
283			// Remote-sandbox rows, synthesized from `/sandboxes`. A missing vault
284			// credential is `status: error` (and needsSetup), not a separate surface.
285			const sandboxItems = buildSandboxConnectorRows(sandboxes).map((row) => ({
286				connector: row.connector,
287				group: undefined,
288				profileCounts: {
289					env: 0,
290					oauth_app: 0,
291					oauth_account: 0,
292					browser_session: 0,
293				},
294				facets: row.facets,
295				needsSetup: !row.sandbox.connected,
296				provider: undefined as InferenceProviderItem | undefined,
297				sandbox: row.sandbox,
298				device: undefined as DeviceWorkerItem | undefined,
299			}));
300	
301			// Paired devices — the local counterpart of a sandbox row. `needsSetup`
302			// stays false: a device with no capabilities is a device, not an
303			// unconfigured connector.
304			const deviceItems = buildDeviceConnectorRows(devices).map((row) => ({
305				connector: row.connector,
306				group: undefined,
307				profileCounts: {
308					env: 0,
309					oauth_app: 0,
310					oauth_account: 0,
311					browser_session: 0,
312				},
313				facets: row.facets,
314				needsSetup: false,
315				isDevice: true,
316				provider: undefined as InferenceProviderItem | undefined,
317				sandbox: undefined as SandboxItem | undefined,
318				device: row.device as DeviceWorkerItem | undefined,
319			}));
320	
321			const connectorItems = Array.from(defMap.values())
322				// The list is the org's INSTALLED connectors only — the browsable catalog
323				// of not-yet-added connectors lives on the "Add connector" page
324				// (/connectors/create). A connector belongs here once it's installed or
325				// has at least one connection (a group). Uninstalled catalog entries are
326				// reachable via "Add connector", so nothing is stranded.
327				.filter(
328					(connector) =>
329						connector.installed ||
330						(groupMap.get(connector.key)?.connection_count ?? 0) > 0,
331				)
332				.map((connector) => {
333					const group = groupMap.get(connector.key);
334					const methods = getAuthMethods(connector.auth_schema);
335					const profileCounts = authProfiles.reduce(
336						(acc, profile) => {
337							if (profile.connector_key !== connector.key) return acc;
338							acc[profile.profile_kind] += 1;
339							return acc;
340						},
341						{ env: 0, oauth_app: 0, oauth_account: 0, browser_session: 0 },
342					);
343					const facets = deriveConnectorFacets(connector, group);
344					const needsSetup = connectorNeedsSetup(
345						connector,
346						group,
347						methods,
348						profileCounts,
349					);
350					return {
351						connector,
352						group,
353						profileCounts,
354						facets,
355						needsSetup,
356						provider: undefined as InferenceProviderItem | undefined,
357						sandbox: undefined as SandboxItem | undefined,
358						device: undefined as DeviceWorkerItem | undefined,
359					};
360				});
361	
362			return [
363				...connectorItems,
364				...providerItems,
365				...sandboxItems,
366				...deviceItems,
367			].sort(
368				(a, b) => {
369					// Every item here is installed or has connections, so "needs setup"
370					// (installed-but-unconfigured) floats to the top as the actionable set.
371					if (a.needsSetup && !b.needsSetup) return -1;
372					if (!a.needsSetup && b.needsSetup) return 1;
373					return a.connector.name.localeCompare(b.connector.name);
374				},
375			);
376		}, [
377			authProfiles,
378			devices,
379			groups,
380			installedDefs,
381			inferenceProviders,
382			sandboxes,
383		]);
384	
385		// Clients are deliberately NOT part of `allItems`: they must not join the
386		// facet chips (no facet describes an inbound grant), the needs-setup sort,
