710	function connectorNeedsSetup(
711		connector: ConnectorDefinitionItem,
712		group: ConnectionConnectorGroup | undefined,
713		methods: ReturnType<typeof getAuthMethods>,
714		profileCounts: Record<
715			"env" | "oauth_app" | "oauth_account" | "browser_session",
716			number
717		>,
718	): boolean {
719		// "Needs setup" means an INSTALLED connector is missing a required binding
720		// (credentials / OAuth app / app install / device) — NOT merely "not added".
721		// Uninstalled catalog entries no longer render in this list, so being
722		// uninstalled is not a setup state here.
723		if (
724			methods.some((m) => m.type === "oauth") &&
725			profileCounts.oauth_app === 0
726		) {
727			return true;
728		}
729		if (methods.some((m) => m.type === "env_keys") && profileCounts.env === 0) {
730			return true;
731		}
732		if (methods.some((m) => m.type === "app_installation") && !group) {
733			return true;
734		}
735		// Device-bound connector (declares a required_capability) with no connection
736		// yet: its runtime binding is unsatisfied. `!group` mirrors the app_install
737		// branch above — resolveDeviceBinding guarantees no connection exists for
738		// these without a valid device, so a group implies the binding is done.
739		if (connector.required_capability && !group) {
740			return true;
741		}
742		return false;
743	}
