import { describe, expect, it } from "vitest";
import {
	type ClientGroup,
	groupClients,
} from "@/lib/connectors/client-rows";
import type { ConnectedClientItem } from "@/lib/api/clients";

function mcp(
	over: Partial<ConnectedClientItem> & { id: string },
): ConnectedClientItem {
	return {
		kind: "mcp",
		status: "disconnected",
		authState: "revoked",
		registrationGroupKey:
			over.registrationGroupKey ??
			JSON.stringify([over.title ?? over.id, over.linkedUserEmail ?? "user"]),
		...over,
	} as ConnectedClientItem;
}

describe("groupClients", () => {
	it("collapses re-registrations of the same app into one row", () => {
		const groups = groupClients([
			mcp({
				id: "a",
				title: "Lobu CLI",
				lastSeenAt: 100,
			}),
			mcp({
				id: "b",
				title: "Lobu CLI",
				lastSeenAt: 300,
			}),
			mcp({
				id: "c",
				title: "Lobu CLI",
				lastSeenAt: 200,
			}),
		]);

		expect(groups).toHaveLength(1);
		expect(groups[0].clientIds.sort()).toEqual(["a", "b", "c"]);
	});

	it("keeps every id so revoke can fan out across registrations", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT" }),
			mcp({ id: "b", title: "ChatGPT" }),
		]);
		expect(groups[0].clientIds).toHaveLength(2);
	});

	it("does not merge different apps", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT" }),
			mcp({ id: "b", title: "Claude" }),
		]);
		expect(groups).toHaveLength(2);
	});
