/**
 * The catalog for one workspace. Owner-scoped because the MCP endpoint and the
 * CLI's configure command both carry the workspace slug — a copied command
 * that points at the wrong workspace is worse than no command.
 */
export function buildConnectorApps(ownerSlug: string): ConnectorAppEntry[] {
	const mcpUrl = buildMcpUrl(ownerSlug);
	return [
		{
			id: "owletto-mac",
			name: "Owletto for Mac",
			icon: APPLE_ICON,
			tagline: "Menu bar app for macOS",
			description:
				"Runs agents on your Mac and brings local context — Screen Time, folders, browser history, calendar — into this workspace. Currently in private beta.",
			devicePlatforms: ["macos"],
			steps: [{ label: "Book access", href: MAC_CONTACT_URL }],
		},
		{
			id: "owletto-chrome",
			name: "Owletto for Chrome",
			icon: <Chrome className="h-4 w-4 shrink-0" />,
			tagline: "Browser extension",
			description:
				"Lets agents read the page you are on and act in your logged-in browser session, and pairs this workspace for one-click connector auth.",
			devicePlatforms: ["chrome-extension"],
			steps: [{ label: "Add to Chrome", href: CHROME_STORE_URL }],
		},
		{
			id: "lobu-cli",
			name: "Lobu CLI",
			icon: <Terminal className="h-4 w-4 shrink-0" />,
			tagline: "Terminal, and local MCP tools",
			description:
				"Authenticates local tools — Claude Code, Cursor, any MCP client on your machine — against this workspace. Headless, no GUI.",
			steps: [
				{
					label: "Install and log in",
					command: `npm i -g @lobu/cli\nlobu login\nlobu memory configure --url ${mcpUrl}`,
				},
			],
		},
		{
			id: "mcp-client",
			name: "MCP client",
			icon: <AppWindow className="h-4 w-4 shrink-0" />,
			tagline: "ChatGPT, Claude, Cursor",
			description:
				"Point any MCP client at this workspace. It authenticates as the person who authorizes it and acts with that person's access — which is why each one shows up on this list by name.",
			steps: [{ label: "Workspace MCP endpoint", command: mcpUrl }],
		},
		{
			id: "lobu-bridge",
			name: "Lobu bridge",
			icon: DOCKER_ICON,
			tagline: "Self-hosted, in a container",
			description:
				"A bridge you run yourself, on a server or VPS. Use it to host connectors that need a persistent always-on environment rather than a laptop that sleeps.",
			catalogOnly: true,
			steps: [{ label: "Run", command: DOCKER_COMMAND }],
		},
	];
}

export function findConnectorApp(
	ownerSlug: string,
	appId: string,
): ConnectorAppEntry | undefined {
	return buildConnectorApps(ownerSlug).find((app) => app.id === appId);
}

/**
 * The apps worth offering on the connectors list: everything not already
 * answered by a paired device, minus the self-hosted path.
 */
export function offerableConnectorApps(
	ownerSlug: string,
	devices: readonly DeviceWorkerItem[],
): ConnectorAppEntry[] {
	const platforms = new Set(
		devices.map((device) => inferredPlatform(device)).filter(Boolean),
	);
	return buildConnectorApps(ownerSlug).filter((app) => {
		if (app.catalogOnly) return false;
		return !app.devicePlatforms?.some((platform) => platforms.has(platform));
	});
}

import { Link } from "@tanstack/react-router";
import { ArrowUpRight, Check, Copy } from "lucide-react";
import { useMemo, useState } from "react";
import {
	ConnectorPageColumn,
	ConnectorPageShell,
} from "@/components/connectors/connector-page-shell";
import {
	DETAIL_CRUMB_LINK_CLASS,
	DetailBreadcrumb,
	DetailHeader,
} from "@/components/connectors/detail-header";
import { PageSection } from "@/components/connectors/page-section";
import {
	PlatformIcon,
	deviceName,
	inferredPlatform,
} from "@/components/devices/device-display";
import { Button } from "@/components/ui/button";
import { useConnectedClients } from "@/lib/api/clients";
import { useDevices } from "@/lib/api/connections";
import {
	type ConnectorAppStep,
	findConnectorApp,
} from "@/lib/connectors/app-catalog";
import { clientRowMeta, groupClients } from "@/lib/connectors/client-rows";
import { deviceRowMeta } from "@/lib/connectors/device-rows";

/**
 * A first-party app — the Mac app, the extension, the CLI, an MCP client —
 * rendered with the same chrome as a connector: `/connectors/app/{id}`.
 *
 * The page answers two questions in order. How do I connect this, and what is
 * connected through it already. The second half is why this belongs under
 * connectors rather than in a docs page: the instructions and the thing they
 * produced are one click apart.
 */
export function AppDetail({
	ownerSlug,
	appId,
}: {
	ownerSlug: string;
	appId: string;
}) {
	const app = useMemo(
		() => findConnectorApp(ownerSlug, appId),
		[ownerSlug, appId],
	);
	// Both queries are cheap and already warm from the connectors list. Fetching
	// them unconditionally keeps the hook order stable across app ids.
	const { data: devices = [] } = useDevices();
	const { data: clients = [] } = useConnectedClients(null);

	const connectedDevices = useMemo(() => {
		const platforms = app?.devicePlatforms;
		if (!platforms?.length) return [];
		return devices.filter((device) => {
			const platform = inferredPlatform(device);
			return platform != null && platforms.includes(platform);
		});
	}, [app, devices]);

	const clientGroups = useMemo(
		() => (app?.id === "mcp-client" ? groupClients(clients) : []),
		[app, clients],
	);

	if (!app) {
		return (
			<ConnectorPageColumn className="space-y-3">
				<p className="text-sm text-muted-foreground">
					There is no app by that name.
				</p>
				<Link
					to="/$owner/connectors"
					params={{ owner: ownerSlug }}
					search={{}}
					className="text-sm text-primary hover:underline"
				>
					Back to connectors
				</Link>
			</ConnectorPageColumn>
		);
	}

	const showsConnected =
		(app.devicePlatforms?.length ?? 0) > 0 || app.id === "mcp-client";

	return (
		<div className="flex flex-1 flex-col">
			<ConnectorPageShell
				header={
					<DetailHeader
						breadcrumb={
							<DetailBreadcrumb
								crumbs={[
									<Link
										key="connectors"
										to="/$owner/connectors"
										params={{ owner: ownerSlug }}
										search={{}}
										className={DETAIL_CRUMB_LINK_CLASS}
									>
										Connectors
									</Link>,
								]}
							/>
						}
						icon={
							<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border text-muted-foreground">
								{app.icon}
							</span>
						}
						title={app.name}
						caption={app.description}
					/>
				}
			>
				<PageSection title="Set up">
					<div className="space-y-3">
						{app.steps.map((step) => (
							<AppStepBlock key={step.label} step={step} />
						))}
					</div>
				</PageSection>

				{showsConnected ? (
					<PageSection
						title="Connected here"
						count={
							connectedDevices.length + clientGroups.length > 0
								? String(connectedDevices.length + clientGroups.length)
								: undefined
						}
					>
						{connectedDevices.length + clientGroups.length === 0 ? (
							<p className="text-xs text-muted-foreground">
								Nothing yet. Finish the steps above and it appears here, and on
								the connectors list.
							</p>
						) : (
							<div className="overflow-hidden rounded-lg border">
								{connectedDevices.map((device, idx) => (
									<Link
										key={device.id}
										to="/$owner/connectors/device/$deviceId"
										params={{ owner: ownerSlug, deviceId: device.id }}
										className={rowClass(
											idx,
											connectedDevices.length + clientGroups.length,
										)}
									>
										<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border">
											<PlatformIcon platform={inferredPlatform(device)} />
										</span>
										<div className="min-w-0 flex-1">
											<p className="truncate text-sm font-medium">
												{deviceName(device)}
											</p>
											<p className="truncate text-xs text-muted-foreground">
												{deviceRowMeta(device)}
											</p>
										</div>
									</Link>
								))}
								{clientGroups.map((group, idx) => (
									<Link
										key={group.key}
										to="/$owner/connectors/client/$clientId"
										params={{ owner: ownerSlug, clientId: group.clientId }}
										className={rowClass(
											connectedDevices.length + idx,
											connectedDevices.length + clientGroups.length,
										)}
									>
										<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border text-muted-foreground">
											{app.icon}
										</span>
										<div className="min-w-0 flex-1">
											<p className="truncate text-sm font-medium">
												{group.title}
											</p>
											<p className="truncate text-xs text-muted-foreground">
												{clientRowMeta(group)}
											</p>
										</div>
									</Link>
								))}
							</div>
						)}
					</PageSection>
				) : null}
			</ConnectorPageShell>
		</div>
	);
}

function rowClass(idx: number, total: number): string {
	return `flex items-center gap-3 px-3 py-2.5 text-left text-muted-foreground transition-colors hover:bg-accent/50 hover:text-foreground ${
		idx === total - 1 ? "" : "border-b"
	}`;
}

/**
 * One instruction. A command is shown in full rather than behind a copy
 * button — the page has the width for it, and someone reading before pasting
 * is exactly the person you want to have read it.
 */
function AppStepBlock({ step }: { step: ConnectorAppStep }) {
	const [copied, setCopied] = useState(false);

	if (step.href) {
		return (
			<a
				href={step.href}
				target="_blank"
				rel="noreferrer"
				className="inline-flex items-center gap-1.5 rounded-md border px-2.5 py-1.5 text-xs font-medium text-primary hover:bg-accent/50"
			>
				{step.label}
				<ArrowUpRight className="h-3 w-3" />
			</a>
		);
	}

	const command = step.command ?? "";
	return (
		<div className="space-y-1.5">
			<p className="text-xs text-muted-foreground">{step.label}</p>
			<div className="flex items-start gap-2 rounded-lg border bg-muted/40 p-2.5">
				<pre className="min-w-0 flex-1 overflow-x-auto font-mono text-xs leading-relaxed">
					{command}
				</pre>
				<Button
					variant="ghost"
					size="sm"
					className="h-6 shrink-0 px-1.5 text-xs"
					onClick={() => {
						if (typeof navigator === "undefined" || !navigator.clipboard) return;
						void navigator.clipboard.writeText(command).then(() => {
							setCopied(true);
							setTimeout(() => setCopied(false), 1500);
						});
					}}
				>
					{copied ? (
						<Check className="h-3.5 w-3.5" />
					) : (
						<Copy className="h-3.5 w-3.5" />
					)}
					<span className="sr-only">Copy</span>
				</Button>
			</div>
		</div>
	);
}

import { createFileRoute } from "@tanstack/react-router";
import { AppDetail } from "@/components/connectors/app-detail";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";

/**
 * A first-party app's instruction page: `/connectors/app/{id}`.
 *
 * Static — the id names a catalog entry in `app-catalog`, not a row in any
 * table. It gets a real route rather than a modal so the Mac app's setup steps
 * are a link someone can paste to a colleague.
 */
export const Route = createFileRoute("/$owner/connectors/app/$appId")({
	component: AppDetailPage,
});

function AppDetailPage() {
	const { owner, appId } = Route.useParams();
	return (
