 * offered a second, less discoverable route to what the default order shows.
 */
export function connectorMatchesFilter(
  item: ConnectorFilterItem,
  filter: ConnectorFilter
): boolean {
  const { connector, facets } = item;
  if (filter === "all") return true;
  if (filter === "data") return facets.data;
  if (filter === "chat") return facets.chat;
  if (filter === "actions") return facets.actions;
  if (filter === "inference") return facets.inference;
  if (filter === "runtime") return facets.runtime === true;
